		/** 
		 * Tests creating a new User.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a User");

			StringBuilder msg = new StringBuilder( "-- Failed to create a User" );

			try {            
				User entity = UserService.getUserInstance().createUser( generateNewEntity() );
				thePrimaryKey = entity.getUserId();
				LOGGER.info( "-- Successfully created a User with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a User. 
		 */
		public User testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created User" );

			User entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read User with primary key" );
			msg.append( thePrimaryKey );
			
			UserFetchOneSummary fetchOneSummary = new UserFetchOneSummary( thePrimaryKey );

			try {
				entity = UserService.getUserInstance().getUser( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found User " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a User.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a User." );

			StringBuilder msg = new StringBuilder( "Failed to update a User : " );        
			User entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created User." );

				// for use later on...
				thePrimaryKey = entity.getUserId();

				UserService proxy = UserService.getUserInstance();            
				proxy.updateUser( entity );   

				LOGGER.info( "-- Successfully saved User - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a User.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created User." );

			try{
			    User entity = testRead(); 
				UserService.getUserInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted User with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete User with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Users.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Users:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all User : " );        
			List<User> collection  = null;

			try {
				// call the static get method on the UserService
				collection = UserService.getUserInstance().getAllUser();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					User entity = null;            
					Iterator<User> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getUserId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

