		protected User generateNewEntity() {
			User entity = new User( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  new Email(),  null,  new HashSet<>(),  new HashSet<>(),  AccountRole.values()[0] );
			
			return( entity );
		}

